typedef struct{uint8_t*data;size_t size;}Source;
static Source load(const char*p){FILE*f=fopen(p,"rb");CHECK(f);CHECK(!fseek(f,0,SEEK_END));long n=ftell(f);CHECK(n>0&&n<1024*1024);rewind(f);Source s={malloc((size_t)n),(size_t)n};CHECK(s.data);CHECK(fread(s.data,1,s.size,f)==s.size&&!fclose(f));return s;}
static CohStatus readat(void*v,uint64_t off,void*out,size_t n){Source*s=v;if(off>s->size||n>s->size-off)return COH_IO;memcpy(out,s->data+(size_t)off,n);return COH_OK;}
