 CohWrTexBasicLookup out,saved;memset(&out,0x55,sizeof(out));saved=out;CohStatus status=guarded?coh_wr_tex_basic_lookup_guarded(r,q,l,&out):coh_wr_tex_basic_lookup(r,q,l,&out);const char*name=q;if(name&&name[0]=='!')name++;size_t n=name?strlen(name):0;int unsafe=name&&n>=4&&n<8&&name[n-4]!='.';
 if(!guarded&&unsafe){CHECK(status==COH_UNSUPPORTED&&!memcmp(&out,&saved,sizeof(out)));strict_refusals++;return;}CHECK(status==COH_OK);char key[128];unsigned flags,calls;int ordinal=original_basic_find(q,guarded,key,&flags,&calls);CHECK(!strcmp(out.key,key)&&out.format_flags==flags);CHECK(out.guarded_short_key_policy==(unsigned)guarded&&out.unresolved_client_semantics==1&&out.input_generation==17);CHECK(out.branch==(!q?COH_WR_BASIC_NULL_REQUEST:ordinal<0?COH_WR_BASIC_NAMESPACE_UNKNOWN:COH_WR_BASIC_OBSERVED_HEADER));CHECK(out.header_ordinal==(ordinal<0?UINT32_MAX:(unsigned)ordinal));CHECK(calls==(unsigned)(q!=NULL));if(ordinal>=0){CohWrTexHeaderInput h;CHECK(coh_wr_tex_inputs_header(r,(unsigned)ordinal,&h)==COH_OK&&!memcmp(out.header_sha256,h.sha256,32));}if(guarded)guarded_count++;else strict_count++;
